check<WhenInSchema<'RateLimitStatus', Accepts<T.RateLimitStatus, M<'RateLimitStatus'>>>>()
check<WhenInSchema<'EffectivePermissions', Accepts<T.EffectivePermissions, M<'EffectivePermissions'>>>>()
